  "revision_action": "strengthen",
  "supportive_card_ids": ["C01", "C136", "C147", "C165", "C176", "C183"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01"],
  "claims": [
    {
      "claim": "C01 directly reports that warfarin oral bioavailability is nearly complete in humans, with more than 98% of the absorbed dose eliminated by hepatic metabolism; this is direct human evidence that F is well above 20%.",
      "card_ids": ["C01"]
    },
    {
      "claim": "C176 reports that studied coumarins rapidly permeate Caco-2 monolayers with higher apical-to-basolateral than basolateral-to-apical permeability, indicating that efflux does not limit absorption for the coumarin class; this is mechanistically supportive for the warfarin coumarin scaffold, though not warfarin-specific.",
      "card_ids": ["C176"]
    },
    {
      "claim": "C136 shows pH-dependent passive transport for weakly acidic compounds with enhanced absorptive permeability at acidic pH, consistent with warfarin (pKa 4.48) being absorbed in the stomach/upper GI; C147, C165, and C183 provide related weak-acid carrier-transport context, but none are warfarin-specific.",
      "card_ids": ["C136", "C147", "C165", "C183"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C136", "C147", "C165", "C176", "C183"]
    }
  ],
  "evidence_gaps": [
    "C01 is qualitative ('nearly complete') rather than a numeric F value, but it unambiguously places F well above 20%.",
    "No warfarin-specific L3 oral AUC/Cmax, L4 absorption/permeability, or L5 gut-wall efflux/intestinal metabolism records were supplied; L5 records are from other coumarins and weak acids.",
    "No direct measurement of warfarin intestinal first-pass or efflux was provided; however, the direct human bioavailability outcome already establishes the threshold result.",
    "L5 mechanistic records have limited transferability because they are not warfarin-specific."
  ],
  "decision_summary": "Direct human evidence (C01) reports warfarin oral bioavailability is nearly complete, clearly supporting F >= 20%. L5 gut-wall efflux and intestinal metabolism records are not warfarin-specific but mechanistically support coumarin/weak-acid absorption without efflux limitation. Prediction remains high."
}

